"use client";
import { useEffect, useRef, useState } from "react";
import { Check, ChevronDown, CreditCard, Plus, UserRound, Wallet } from "lucide-react";
import Widget, { type WidgetKind } from "./financial-widget";
import CashFlowChart from "./cash-flow-chart";
import PaymentsPanel from "./payments-panel";
export default function Dashboard() {
 const [menu, setMenu] = useState(false);
 const [profile, setProfile] = useState(false);
 const [widgets, setWidgets] = useState<WidgetKind[]>(["Savings", "Credit"]);
 const menuRef = useRef<HTMLDivElement>(null);
 const accountRef = useRef<HTMLDivElement>(null);
 useEffect(() => { const close = (event: MouseEvent) => { if (menuRef.current && !menuRef.current.contains(event.target as Node) && !accountRef.current?.contains(event.target as Node)) { setMenu(false); setProfile(false); } }; const escape = (event: KeyboardEvent) => { if (event.key === "Escape") { setMenu(false); setProfile(false); } }; document.addEventListener("mousedown", close); document.addEventListener("keydown", escape); return () => { document.removeEventListener("mousedown", close); document.removeEventListener("keydown", escape); }; }, []);
 return <><header className="topbar"><div className="nav-inner"><a className="brand" href="/" aria-label="PNC home">PNC<span className="brand-divider" /><span className="brand-product">360° Navigator</span></a><nav aria-label="Main navigation"><a href="/" className="nav-active" aria-current="page">Home</a><button disabled title="Health page coming soon">Health</button><button disabled title="Future page coming soon">Future</button></nav><div className="account-wrap" ref={accountRef}><button className="account-button" aria-label="Open account menu" aria-expanded={profile} onClick={() => { setProfile(!profile); setMenu(false); }}><span className="avatar"><UserRound size={17} /></span><span>My account</span><ChevronDown size={14} /></button>{profile && <div className="dropdown account-menu"><strong>Demo account</strong><p>PNC 360° Financial Health Navigator</p><small>Using sample financial data</small><button onClick={() => setProfile(false)}>Close menu</button></div>}</div></div></header><main><div className="page-heading"><div><h1>Overview</h1></div><div className="widget-menu-wrap" ref={menuRef}><button className="add-widget" aria-expanded={menu} onClick={() => { setMenu(!menu); setProfile(false); }}><Plus size={16} />Add Widget</button>{menu && <div className="dropdown widget-menu"><p>PERSONALIZE YOUR OVERVIEW</p>{(["Savings", "Credit"] as const).map(kind => <button disabled={widgets.includes(kind)} key={kind} onClick={() => { setWidgets([...widgets, kind]); setMenu(false); }}>{kind === "Savings" ? <Wallet size={17} /> : <CreditCard size={17} />}<span>{kind}</span>{widgets.includes(kind) ? <span className="added">Added <Check size={13} /></span> : <Plus size={15} />}</button>)}<small>Remove a widget to add it again.</small></div>}</div></div><section className="summary-row" aria-label="Financial summary"><div className="balance-card"><div className="balance-label"><span className="balance-icon"><Wallet size={18} /></span>Total Balance<span className="balance-badge">ALL ACCOUNTS</span></div><div className="balance-value">$100,000<span>.00</span></div><div className="balance-bottom"><span className="mock-label">Demo balance</span></div></div><div className="widgets">{widgets.map(kind => <Widget key={kind} kind={kind} onRemove={() => setWidgets(widgets.filter(widget => widget !== kind))} />)}{widgets.length === 0 && <button className="empty-widgets" onClick={() => setMenu(true)}><Plus size={20} />Add Savings or Credit to your overview</button>}</div></section><div className="detail-grid"><CashFlowChart /><PaymentsPanel /></div><footer className="page-footer"><span>PNC 360° Financial Health Navigator</span><span>Hackathon preview · All figures are sample data</span></footer></main></>;
}


